class Tool:
    # class attributes
    _number = 0
    _name = "Tool"
    _nozzleSize = 0.4
    _offsets = {"X":0, "Y": 0, "Z": 0}
    
    def __init__(self, number=0, name="Tool", nozzleSize=0.4, offsets={"X":0, "Y": 0, "Z": 0}):
        self._number = number
        self._name = name
        self._nozzleSize = nozzleSize
        self._offsets = offsets

    def getJSON(self):
        return({
            "number": self._number,
            "name": self._name, 
            "nozzleSize": self._nozzleSize,
            "offsets": [ self._offsets["X"], self._offsets["Y"], self._offsets["Z"] ]
        })
    
    def __str__(self):
        toolNumber = str(self._number)
        toolName = self._name
        toolNozzleSize = str(self._nozzleSize)
        toolOffsets = "(" + str(self._offsets["X"]) +","+str(self._offsets["Y"])+","+str(self._offsets["Z"])+ ")"
        return( toolNumber + " " + toolName + " " + toolNozzleSize + " " + toolOffsets )

    def __rep__(self):
        return("Hello")

